samples.raw_completion:
// One-hot state encoding: state s is encoded as a 3-bit vector such that
// s[2] is the highest bit, s[1] is the second bit, and s[0] is the lowest
// bit. The state s = [2,1,0] is therefore encoded as the 3-bit vector
// [1,0,0].
//
// The combinational next state logic F(s, x) takes the current state and
// the input x and computes the next state.
//
// The output logic G(s, x) takes the current state and the input x and
// computes the output z.
//
// This combined next state and output logic can be generated automatically
// for a given transition table using a tool such as
// https://github.com/sylefeb/fsm2mlab.
module TopModule(
    input  clk,
    input  x,
    input  [2:0] y,
    output reg Y0,
    output reg z
);
    reg [2:0] s;
    always @(posedge clk) begin
        case ({s, x})
            // State 000
            6'b000000: begin Y0=1; z=0; s=3'b000; end
            // State 001
            6'b000001: begin Y0=1; z=0; s=3'b001; end
            // State 010
            6'b000010: begin Y0=1; z=0; s=3'b010; end
            // State 011
            6'b000011: begin Y0=0; z=1; s=3'b001; end
            // State 100
            6'b000100: begin Y0=0; z=1; s=3'b100; end
            default: begin Y0=1'bx; z=1'bx; s=3'bx; end
        endcase
    end
endmodule

